package com.bank.core;

import java.math.BigDecimal;
import java.util.Objects;

// Implicitly extends java.lang.Object — inherits all Object methods.
public class Account {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    @Override
    public String toString() { // readable logs instead of Account@1b6d3586
        return "Account[" + accountId + ", " + holderName + ", " + balance + "]";
    }

    @Override
    public boolean equals(Object o) { // logical equality by accountId
        if (this == o) return true;
        if (!(o instanceof Account)) return false;
        Account other = (Account) o;
        return Objects.equals(accountId, other.accountId);
    }

    @Override
    public int hashCode() { // MUST be consistent with equals
        return Objects.hash(accountId);
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
}
