package com.bank.core;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.*;

public class ObjectMethodsDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account a1 = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account a2 = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));

        // toString
        log.info(() -> "toString → " + a1);

        // equals + hashCode
        log.info(() -> "a1.equals(a2) → " + a1.equals(a2)
                        + ", same hashCode → " + (a1.hashCode() == a2.hashCode()));

        // works as a HashMap key because equals/hashCode are consistent
        Map<Account, String> tier = new HashMap<>();
        tier.put(a1, "PREMIUM");
        log.info(() -> "lookup with equal key a2 → " + tier.get(a2));

        // getClass
        log.info(() -> "getClass → " + a1.getClass().getName());
    }
}
